#[derive(Subcommand)]
pub enum NetworkCommand {
    #[command(name = "all")]
    All(Box<NetworkAllArgs>),
    #[command(name = "create")]
    Create(Box<NetworkCreateArgs>),
    #[command(name = "import")]
    Import(Box<NetworkImportArgs>),
    #[command(name = "inspect")]
    Inspect(Box<NetworkInspectArgs>),
    #[command(name = "networks-to-sync")]
    NetworksToSync(Box<NetworkNetworksToSyncArgs>),
    #[command(name = "one")]
    One(Box<NetworkOneArgs>),
    #[command(name = "recreate")]
    Recreate(Box<NetworkRecreateArgs>),
    #[command(name = "remove")]
    Remove(Box<NetworkRemoveArgs>),
    #[command(name = "resync")]
    Resync(Box<NetworkResyncArgs>),
}

impl NetworkCommand {
    fn into_invocation(self) -> Result<ImperativeInvocation, ImperativeInputError> {
        match self {
            Self::All(args) => build_invocation(
                &OPERATIONS[297],
                None,
                vec![("serverId", args.query_server_id)],
                vec![],
            ),
            Self::Create(args) => build_invocation(
                &OPERATIONS[298],
                args.body_json,
                vec![],
                vec![
                    ("name", args.body_name),
                    ("driver", args.body_driver),
                    ("internal", args.body_internal),
                    ("attachable", args.body_attachable),
                    ("enableIPv4", args.body_enable_i_pv4),
                    ("enableIPv6", args.body_enable_i_pv6),
                    ("mtu", args.body_mtu),
                    ("ipam", args.body_ipam),
                    ("serverId", args.body_server_id),
                ],
            ),
            Self::Import(args) => build_invocation(
                &OPERATIONS[299],
                args.body_json,
                vec![],
                vec![
                    ("serverId", args.body_server_id),
                    ("names", args.body_names),
                ],
            ),
            Self::Inspect(args) => build_invocation(
                &OPERATIONS[300],
                None,
                vec![("networkId", args.query_network_id)],
                vec![],
            ),
            Self::NetworksToSync(args) => build_invocation(
                &OPERATIONS[301],
                None,
                vec![("serverId", args.query_server_id)],
                vec![],
            ),
            Self::One(args) => build_invocation(
                &OPERATIONS[302],
                None,
                vec![("networkId", args.query_network_id)],
                vec![],
            ),
            Self::Recreate(args) => build_invocation(
                &OPERATIONS[303],
                args.body_json,
                vec![],
                vec![("networkId", args.body_network_id)],
            ),
            Self::Remove(args) => build_invocation(
                &OPERATIONS[304],
                args.body_json,
                vec![],
                vec![("networkId", args.body_network_id)],
            ),
            Self::Resync(args) => build_invocation(
                &OPERATIONS[305],
                args.body_json,
                vec![],
                vec![("networkId", args.body_network_id)],
            ),
        }
    }
}

