#[derive(Subcommand)]
pub enum RegistryCommand {
    #[command(name = "all")]
    All,
    #[command(name = "create")]
    Create(Box<RegistryCreateArgs>),
    #[command(name = "one")]
    One(Box<RegistryOneArgs>),
    #[command(name = "remove")]
    Remove(Box<RegistryRemoveArgs>),
    #[command(name = "test-registry")]
    TestRegistry(Box<RegistryTestRegistryArgs>),
    #[command(name = "test-registry-by-id")]
    TestRegistryById(Box<RegistryTestRegistryByIdArgs>),
    #[command(name = "update")]
    Update(Box<RegistryUpdateArgs>),
}

impl RegistryCommand {
    fn into_invocation(self) -> Result<ImperativeInvocation, ImperativeInputError> {
        match self {
            Self::All => build_invocation(&OPERATIONS[428], None, vec![], vec![]),
            Self::Create(args) => build_invocation(
                &OPERATIONS[429],
                args.body_json,
                vec![],
                vec![
                    ("registryName", args.body_registry_name),
                    ("username", args.body_username),
                    ("password", args.body_password),
                    ("registryUrl", args.body_registry_url),
                    ("registryType", args.body_registry_type),
                    ("imagePrefix", args.body_image_prefix),
                    ("serverId", args.body_server_id),
                ],
            ),
            Self::One(args) => build_invocation(
                &OPERATIONS[430],
                None,
                vec![("registryId", args.query_registry_id)],
                vec![],
            ),
            Self::Remove(args) => build_invocation(
                &OPERATIONS[431],
                args.body_json,
                vec![],
                vec![("registryId", args.body_registry_id)],
            ),
            Self::TestRegistry(args) => build_invocation(
                &OPERATIONS[432],
                args.body_json,
                vec![],
                vec![
                    ("registryName", args.body_registry_name),
                    ("username", args.body_username),
                    ("password", args.body_password),
                    ("registryUrl", args.body_registry_url),
                    ("registryType", args.body_registry_type),
                    ("imagePrefix", args.body_image_prefix),
                    ("serverId", args.body_server_id),
                ],
            ),
            Self::TestRegistryById(args) => build_invocation(
                &OPERATIONS[433],
                args.body_json,
                vec![],
                vec![
                    ("registryId", args.body_registry_id),
                    ("serverId", args.body_server_id),
                ],
            ),
            Self::Update(args) => build_invocation(
                &OPERATIONS[434],
                args.body_json,
                vec![],
                vec![
                    ("registryId", args.body_registry_id),
                    ("registryName", args.body_registry_name),
                    ("imagePrefix", args.body_image_prefix),
                    ("username", args.body_username),
                    ("password", args.body_password),
                    ("registryUrl", args.body_registry_url),
                    ("createdAt", args.body_created_at),
                    ("registryType", args.body_registry_type),
                    ("organizationId", args.body_organization_id),
                    ("serverId", args.body_server_id),
                ],
            ),
        }
    }
}

