#[derive(Subcommand)]
pub enum SshKeyCommand {
    #[command(name = "all")]
    All,
    #[command(name = "all-for-apps")]
    AllForApps,
    #[command(name = "create")]
    Create(Box<SshKeyCreateArgs>),
    #[command(name = "generate")]
    Generate(Box<SshKeyGenerateArgs>),
    #[command(name = "one")]
    One(Box<SshKeyOneArgs>),
    #[command(name = "remove")]
    Remove(Box<SshKeyRemoveArgs>),
    #[command(name = "update")]
    Update(Box<SshKeyUpdateArgs>),
}

impl SshKeyCommand {
    fn into_invocation(self) -> Result<ImperativeInvocation, ImperativeInputError> {
        match self {
            Self::All => build_invocation(&OPERATIONS[521], None, vec![], vec![]),
            Self::AllForApps => build_invocation(&OPERATIONS[522], None, vec![], vec![]),
            Self::Create(args) => build_invocation(
                &OPERATIONS[523],
                args.body_json,
                vec![],
                vec![
                    ("name", args.body_name),
                    ("description", args.body_description),
                    ("privateKey", args.body_private_key),
                    ("publicKey", args.body_public_key),
                    ("organizationId", args.body_organization_id),
                ],
            ),
            Self::Generate(args) => build_invocation(
                &OPERATIONS[524],
                args.body_json,
                vec![],
                vec![("type", args.body_type)],
            ),
            Self::One(args) => build_invocation(
                &OPERATIONS[525],
                None,
                vec![("sshKeyId", args.query_ssh_key_id)],
                vec![],
            ),
            Self::Remove(args) => build_invocation(
                &OPERATIONS[526],
                args.body_json,
                vec![],
                vec![("sshKeyId", args.body_ssh_key_id)],
            ),
            Self::Update(args) => build_invocation(
                &OPERATIONS[527],
                args.body_json,
                vec![],
                vec![
                    ("name", args.body_name),
                    ("description", args.body_description),
                    ("lastUsedAt", args.body_last_used_at),
                    ("sshKeyId", args.body_ssh_key_id),
                ],
            ),
        }
    }
}

